def main() -> None:
    text = SRC.read_text(encoding="utf-8")
    for mapping in (REPLACEMENTS, MORE_REPLACEMENTS, TAIL_REPLACEMENTS):
        for src, dst in mapping.items():
            if src not in text:
                print(f"[warn] source text not found: {src[:90]!r}")
            text = text.replace(src, dst)

    preamble = "% 中文阅读版，由 scripts/build_chinese_full_paper.py 从 full_paper_6_17.tex 生成。\n"
    DST.write_text(preamble + text, encoding="utf-8")
    print(f"Wrote {DST}")


if __name__ == "__main__":
    main()
